import React, { useState } from "react";

export default function ChatInput({ onSend, onUpload, loading }){
  const [text, setText] = useState("");
  const [file, setFile] = useState(null);

  const doSend = () => {
    onSend(text);
    setText("");
  };

  return (
    <>
      <div className="chat-input">
        <input className="form-control" placeholder="Type: Analyze Wakad or Compare X and Y" value={text}
          onChange={e=>setText(e.target.value)} onKeyDown={e=>{ if(e.key==="Enter") doSend(); }} />
        <button className="btn btn-accent" onClick={doSend} disabled={loading}>{loading? "..." : "Send"}</button>
      </div>

      <div style={{marginTop:10, display:"flex", gap:8}}>
        <input type="file" onChange={e=>setFile(e.target.files[0])} />
        <button className="btn btn-outline-primary" onClick={()=>{ if(file) onUpload(file); else alert("Choose a file first")}}>Upload Excel</button>
        <a className="btn btn-outline-secondary" href="#" onClick={(e)=>{e.preventDefault(); alert("Tip: try queries like 'Analyze Wakad'");}}>Help</a>
      </div>
    </>
  );
}
